package com.bank.successor;

import java.util.*;

public class SuccessorRouter {

    public RouteNode levelOrderSuccessor(RouteNode root, int target) {
        if (root == null) return null;
        Queue<RouteNode> queue = new LinkedList<>();
        queue.offer(root);
        while (!queue.isEmpty()) {
            RouteNode node = queue.poll();
            // Enqueue children FIRST so the next-level start is present at a boundary.
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
            if (node.id == target) break;      // found target; successor is queue head
        }
        return queue.peek();                    // next to be dequeued, or null
    }
}
