package com.bank.successor;

import java.util.logging.Logger;

public class SuccessorDemo {
    private static final Logger log = Logger.getLogger(SuccessorDemo.class.getName());

    public static void main(String[] args) {
        // BFS order: 1,2,3,4,5
        RouteNode root = new RouteNode(1);
        root.left = new RouteNode(2);
        root.right = new RouteNode(3);
        root.left.left = new RouteNode(4);
        root.left.right = new RouteNode(5);

        RouteNode succ = new SuccessorRouter().levelOrderSuccessor(root, 3);
        log.info("Successor of 3: " + (succ == null ? "none" : succ.id));
    }
}
